solutions.naive:
class Solution:
    def minimumLength(self, s: str) -> int:
        while len(s) > 1 and s[0] == s[-1]:
            ch=s[0]; l=0
            while l < len(s) and s[l] == ch: l += 1
            r=len(s)-1
            while r >= l and s[r] == ch: r -= 1
            s=s[l:r+1]
        return len(s)

solutions.better:
class Solution:
    def minimumLength(self, s: str) -> int:
        seen=[]; l,r=0,len(s)-1
        while l < r and s[l] == s[r]:
            ch=s[l]
            while l <= r and s[l] == ch: l += 1
            while l <= r and s[r] == ch: r -= 1
            seen.append((l,r))
        return max(0,r-l+1)

